import itertools

def solve(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    total_sum = 0
    for p in perms:
        # Calculate sign
        inversions = 0
        for i in range(n):
            for j in range(i + 1, n):
                if p[i] > p[j]:
                    inversions += 1
        sigma = 1 if inversions % 2 == 0 else -1

        # Calculate fixed points
        fixed_points = 0
        for i in range(n):
            if p[i] == i + 1:
                fixed_points += 1

        total_sum += sigma / (fixed_points + 1)
    return total_sum

for n in range(1, 7):
    print(f"n={n}: {solve(n)}")
